+      final resolver = AgentPackResolver(packsRoot: packsRoot);
+      _writeFile('child.json', '''{
+        "name":"child",
+        "parent":{"path":"${zip.path.replaceAll('\\', '/')}"},
+        "params":{"fromChild":"yes"}
