          throwsA(
            isA<AgentPackException>().having(
              (e) => e.message,
              'message',
              contains('Malformed registry catalog'),
            ),
          ),
        );
      } finally {
        server.isolate.kill();
      }
    });

    test('@version with a mismatching .sha256 fails the checksum', () async {
