          packRoot: packRoot,
          entryFile: entryFile,
          agent: agent,
          version: version);
    } finally {
      // Clean up a downloaded temp zip (local files are left in place).
      if (base.startsWith('http') && zipFile.existsSync()) zipFile.deleteSync();
    }
