          '${sha256.convert(zipBytes)}  cdn_agent-3.1.0.zip',
        ),
        '/catalog.json': utf8.encode(jsonEncode({'cdn_agent': '3.1.0'})),
      });
      try {
        final r = AgentPackResolver(
          packsRoot: packsRoot,
          registryBaseUrl: 'http://127.0.0.1:${server.port}/redirect',
        );
