        final r = AgentPackResolver(
          packsRoot: packsRoot,
          registryBaseUrl: 'http://127.0.0.1:${server.port}',
        );
        expect(
          () => r.resolve('unknown_agent@latest'),
          throwsA(
            isA<AgentPackException>().having(
              (e) => e.message,
